            "type": "null"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "state": {
            "const": "approved"
          }
        }
      },
      "then": {
        "properties": {
          "approval_state": {
            "const": "approved"
          }
        },
        "required": [
          "resolution_id",
          "authority_ref"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "state": {
