        "rejected",
        "withdrawn"
      ]
    },
    "asked_at": {
      "format": "date-time",
      "type": "string"
    },
    "attempt_id": {
      "minLength": 1,
      "type": "string"
    },
    "authority_ref": {
      "type": [
        "string",
        "null"
      ]
    },
    "gate_id": {
      "minLength": 1,
      "type": "string"
    },
    "gate_ref": {
      "minLength": 1,
      "type": "string"
    },
    "question": {
      "minLength": 1,
